VALUES (NULL, NULL, 111846, 'Void Bastards', 'Void Bastards', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co497z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8jq.jpg', '"Inspired by BioShock and System Shock 2, Void Bastards is a revolutionary new strategy-shooter that will test your wits as well as exercise your aim. Can you lead the misfit prisoners of the Void Ark through the derelict spaceships and myriad dangers of the Sargasso Nebula?"', 'https://www.igdb.com/games/void-bastards', '["PlayStation 4", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.7, 0, 9.51, '2026-11-21 13:07:40', '2026-11-21 13:07:40')
