VALUES (NULL, NULL, 2651, 'Destroy All Humans!', 'Destroy All Humans!', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1umj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6owc.jpg', 'Destroy All Humans! is an action-adventure video game that stands as the inaugural entry in the Destroy All Humans! franchise. It unfolds in 1959 in the United States. The game satirises the lifestyles, pop culture, and political attitudes of that era. Players take on the role of Cryptosporidium 137, a member of the fictional alien race known as "Furons." Functioning as a Furon spy hitman, Cryptosporidium 137 invades Earth with the mission of harvesting human DNA to sustain the cloning process for his species.', 'https://www.igdb.com/games/destroy-all-humans', '["Xbox", "PlayStation 4", "PlayStation 2"]', NULL, 7.1, 0, 10.07, '2026-11-21 13:07:40', '2026-11-21 13:07:40')
