VALUES (NULL, NULL, 190197, 'The Fabulous Fear Machine', 'The Fabulous Fear Machine', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4p7v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1fli.jpg', 'Everything you’ve ever dreamed of can be yours with The Fabulous Fear Machine, a narrative-driven strategy game with a pulp horror style. Become a Master of the Machine, spread the darkest Legends of urban myth, and let fear rule the world.', 'https://www.igdb.com/games/the-fabulous-fear-machine', '["PC (Microsoft Windows)"]', NULL, 9.0, 0, 9.51, '2026-11-21 13:07:40', '2026-11-21 13:07:40')
