VALUES (NULL, NULL, 7334, 'Bloodborne', 'Bloodborne', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob99l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3mkv.jpg', 'An action RPG in which the player embodies a Hunter who, after being transfused with the mysterious blood local to the city of Yharnam, sets off into a "night of the Hunt", an extended night in which Hunters may phase in and out of dream and reality in order to thin the outbreak of abominable beasts that plague the land and, for the more resilient and insightful Hunters, uncover the answers to the Hunt''s many mysteries.', 'https://www.igdb.com/games/bloodborne', '["PlayStation 4"]', NULL, 9.1, 0, 9.61, '2026-11-21 13:07:40', '2026-11-21 13:07:40')
