VALUES (NULL, NULL, 247, 'Half-Life 2: Episode Two', 'Half-Life 2: Episode Two', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mw2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/armmu.jpg', 'Half-Life 2: Episode Two is a first-person shooter set in the aftermath of the Citadel''s destruction. Players control Gordon Freeman as he and Alyx Vance travel through forests and underground tunnels toward a resistance base, facing Combine forces and new enemy types along the way. The game emphasizes vehicle-based combat sequences alongside the series'' physics-driven puzzles and gunplay.', 'https://www.igdb.com/games/half-life-2-episode-two', '["PlayStation 3", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, 7.9, 0, 9.54, '2026-11-21 13:07:40', '2026-11-21 13:07:40')
