VALUES (NULL, NULL, 339932, 'To the Moon', 'To the Moon', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9o96.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3fr0.jpg', 'TO THE MOON is an addictive vertical platformer where every jump counts. Guide your character through shifting platforms as you time each leap perfectly to ascend toward the luminous moon.', 'https://www.igdb.com/games/to-the-moon--1', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 9.51, '2026-11-21 13:07:40', '2026-11-21 13:07:40')
