VALUES (NULL, NULL, 121084, 'In Sound Mind', 'In Sound Mind', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3p6y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arloo.jpg', 'In Sound Mind is an imaginative first-person psychological horror with frenetic puzzles, unique boss fights, and original music. Journey within the inner workings of the one place you can’t seem to escape - your own mind.', 'https://www.igdb.com/games/in-sound-mind', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5", "Nintendo Switch"]', NULL, 8.5, 0, 8.56, '2026-11-21 13:07:40', '2026-11-21 13:07:40')
