VALUES (NULL, NULL, 279642, 'Lost Records: Bloom & Rage', 'Lost Records: Bloom & Rage', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9p3a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3r3y.jpg', 'Lost Records: Bloom & Rage is a brand-new story-driven journey through time from the creative minds behind Life is Strange. The magical summer of 1995 is one of self-discovery and forging unbreakable bonds for high school friends Swann, Nora, Autumn, and Kat. 27 years of no contact later, fate reunites them to confront the long-buried secret that made them promise to never speak again.', 'https://www.igdb.com/games/lost-records-bloom-and-rage', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.5, 0, 9.01, '2026-11-21 13:07:40', '2026-11-21 13:07:40')
