VALUES (NULL, NULL, 316987, 'No, I''m Not A Human', 'No, I''m Not A Human', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coajvh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3fg1.jpg', 'An intimate story about a disaster and guests from underground. People are breaking into your home, but not all of them are true people.', 'https://www.igdb.com/games/no-im-not-a-human', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5", "Nintendo Switch"]', NULL, 7.5, 0, 9.01, '2026-11-21 13:07:40', '2026-11-21 13:07:40')
