VALUES (NULL, NULL, 126211, 'Pagan: Autogeny', 'Pagan: Autogeny', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co781t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arj4t.jpg', 'A thousand worlds surround our own, composed of bits and bytes. When they die, where do they go; what secrets do they hide? Stumble ye, wayfarer, through the wreckage of a dead MMO.', 'https://www.igdb.com/games/pagan-autogeny', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 10.515, '2026-11-21 13:07:40', '2026-11-21 13:07:40')
