VALUES (NULL, NULL, 145858, 'Lorn''s Lure', 'Lorn''s Lure', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ugv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar36lj.jpg', 'An android is led through a vast structure by a glitch in his visual system. Lorn''s Lure is an atmospheric narrative first-person platformer with novel climbing mechanics and modernized retro 3D graphics.', 'https://www.igdb.com/games/lorns-lure', '["Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 6.3, 0, 9.51, '2026-11-21 13:07:40', '2026-11-21 13:07:40')
