VALUES (NULL, NULL, 507, 'I Am Alive', 'I Am Alive', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2sn0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar10ti.jpg', 'I Am Alive casts the player as a lone survivor in a believable, dark and insecure post-apocalyptic world. One year after the Event, a worldwide cataclysmic event that wiped most of the human race, a man struggles for survival in a desolate city as he tries to reunite with his long-lost wife and daughter.', 'https://www.igdb.com/games/i-am-alive', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 6.8, 0, 9.01, '2026-11-21 13:07:40', '2026-11-21 13:07:40')
