VALUES (NULL, NULL, 54842, 'Biomutant', 'Biomutant', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rse.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/yr81zti6usqvly1oonpc.jpg', 'Biomutant is an open-world, post-apocalyptic Kung-Fu fable RPG, with a unique martial arts styled combat system allowing you to mix melee, shooting and mutant ability action. A plague is ruining the land and the Tree-of-Life is bleeding death from its roots. The Tribes stand divided. Explore a world in turmoil and define its fate, will you be its savior or lead it to an even darker destiny?', 'https://www.igdb.com/games/biomutant', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 6.7, 0, 8.01, '2026-11-21 13:07:40', '2026-11-21 13:07:40')
