INSERT INTO "recommendations" ("tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at")
VALUES (NULL, NULL, 24054, 'Caves of Qud', 'Caves of Qud', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7eda.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arhva.jpg', 'Caves of Qud is a science fantasy roguelike epic steeped in retro-futurism, deep simulation, and swathes of sentient plants. The game weaves a handwritten narrative through rich physical, social, and historical simulations. The result is a hybrid handcrafted & procedurally-generated world where you can do just about anything. Assemble your character from over 70 mutations and defects, and 24 castes and kits - it’s all the character diversity you could want. Explore procedurally-generated regions with some familiar locations - each world is nearly 1 million maps large.', 'https://www.igdb.com/games/caves-of-qud', '["Linux", "Nintendo Switch 2", "PC (Microsoft Windows)", "Mac", "Nintendo Switch"]', NULL, 9.1, 0, 9.52, '2026-11-19 20:56:22', '2026-11-21 13:07:40')
