VALUES (NULL, NULL, 14761, 'Rain World', 'Rain World', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co24pm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6vy.jpg', 'Rain World is a survival platformer set in an abandoned industrial environment ravaged by a shattered ecosystem. Bone-crushingly intense rains pound the surface, making life as we know it almost impossible. The creatures in this world hibernate most of the time, but in the few brief dry periods they go out in search of food.', 'https://www.igdb.com/games/rain-world', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 6.9, 0, 1.18533333333333317e+01, '2026-11-19 20:56:22', '2026-11-21 13:07:40')
