VALUES (NULL, NULL, 159735, 'Dread Delusion', 'Dread Delusion', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3oxx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aryds.jpg', 'Dread Delusion is an open world RPG brimming with strange places and dark perils. Carve your own path through the flying continents of a shattered land. Discover curious towns, unearth occult secrets, master powerful magic - and change the world through your choices.', 'https://www.igdb.com/games/dread-delusion', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 6.6, 0, 9.065, '2026-11-19 20:56:22', '2026-11-21 13:07:40')
