VALUES (NULL, NULL, 3225, 'No Man''s Sky', 'No Man''s Sky', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocnm2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/s81kuicumnoogbv7pmel.jpg', 'No Man''s Sky is an action-adventure survival game set in a procedurally generated universe containing over 18 quintillion planets. Players explore star systems, gather resources, trade with alien species, and upgrade their equipment while following an overarching narrative involving a mysterious entity called the Atlas. The game is built around four pillars: exploration, survival, combat, and trading. Since its 2016 launch, it has received numerous free updates adding multiplayer, base building, fleet management, and virtual reality support.', 'https://www.igdb.com/games/no-man-s-sky', '["Xbox Series X|S", "PlayStation VR2", "PlayStation 4", "Nintendo Switch 2", "PlayStation VR", "PC (Microsoft Windows)", "SteamVR", "PlayStation 5", "Mac", "Oculus Rift", "Xbox One"]', NULL, 7.3, 0, 13.0, '2026-11-19 20:56:22', '2026-11-21 13:07:40')
