VALUES (NULL, NULL, 1377, 'Spec Ops: The Line', 'Spec Ops: The Line', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2acb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arqh2.jpg', 'A third-person shooter in which three American soldiers led by Capt. Walker are sent to Dubai in order to recover whoever remains of an infantry unit, the 33rd Battalion, until they decide to take action against the militants situated in the city. As they progress, however, the logistical and ethical complexity of their objective deepens, and their perception of themselves, and their enemy, is put into question.', 'https://www.igdb.com/games/spec-ops-the-line', '["PlayStation 3", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, 7.9, 0, 10.82, '2026-11-19 20:56:22', '2026-11-21 13:07:40')
