VALUES (NULL, NULL, 152271, 'Citizen Sleeper', 'Citizen Sleeper', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4zl5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar61my.jpg', 'Roleplaying in the ruins of interplanetary capitalism. Live the life of an escaped worker, washed-up on a lawless station at the edge of an interstellar society. Inspired by the flexibility and freedom of TTRPGs, explore the station, choose your friends, escape your past and change your future.', 'https://www.igdb.com/games/citizen-sleeper', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.0, 0, 9.77, '2026-11-19 20:56:22', '2026-11-21 13:07:40')
