VALUES (NULL, NULL, 113114, 'The Outer Worlds', 'The Outer Worlds', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2eew.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5qt.jpg', 'The Outer Worlds is a new single-player sci-fi RPG from Obsidian Entertainment and Private Division. As you explore the furthest reaches of space and encounter a host of factions all vying for power, who you decide to become will determine the fate of everyone in Halcyon. In the corporate equation for the colony, you are the unplanned variable.', 'https://www.igdb.com/games/the-outer-worlds', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 8.2, 0, 6.285, '2026-11-19 20:56:22', '2026-11-21 13:07:40')
