VALUES (NULL, NULL, 76747, 'Atomic Heart', 'Atomic Heart', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co68ag.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1y0l.jpg', 'Atomic Heart is an adventure first-person shooter, events of which unfolds in an alternate universe during the high noon of the Soviet Union. The principal character of the game is a special agent P-3, who after an unsuccessful landing on enterprise "3826" is trying to figure out what went wrong.', 'https://www.igdb.com/games/atomic-heart', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.0, 0, 6.01500000000000056e+00, '2026-11-19 20:56:22', '2026-11-21 13:07:40')
