VALUES (NULL, NULL, 79, 'Stubbs the Zombie in Rebel Without a Pulse', 'Stubbs the Zombie in Rebel Without a Pulse', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2oy0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7lr.jpg', 'Be the Zombie. Kick A** and Take Brains. It’s 1959 and the city of Punchbowl, PA, is a beacon of progress and ideal living. Show the living that law and order are no match for a dead man on a mission!', 'https://www.igdb.com/games/stubbs-the-zombie-in-rebel-without-a-pulse', '["Xbox", "PlayStation 4", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 6.8, 0, 6.275, '2026-11-19 20:56:22', '2026-11-21 13:07:40')
