VALUES (NULL, NULL, 1871, 'The Walking Dead', 'The Walking Dead', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2j1g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4s7f.jpg', 'The Walking Dead: Season One (also known as The Walking Dead: The Game) is an episodic interactive drama graphic adventure video game developed and published by Telltale Games. Based on Robert Kirkman''s The Walking Dead comic book series, the game consists of five episodes, released between April and November 2012. It is available for Android, iOS, Kindle Fire HDX, Microsoft Windows, Mac OS X, PlayStation 3, PlayStation Vita, Xbox 360, PlayStation 4 and Xbox One. The game is the first of The Walking Dead video game series published by Telltale.', 'https://www.igdb.com/games/the-walking-dead', '["PlayStation 3", "PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "PlayStation Vita", "Xbox 360", "Xbox One", "Nintendo Switch"]', NULL, 8.5, 0, 6.26500000000000056e+00, '2026-11-19 20:56:22', '2026-11-21 13:07:40')
